            type Vocabulary =
                abstract Item: key: string -> option<Agents.AgentContext>

        module rec StripPath =
            type Vocabulary =
                abstract Item: key: string -> option<Agents.AgentContext>

        type StripPath<'T when 'T :> obj> = U2<StripPath, unit>

        type RecursiveZodFormattedError<'T> =
            U2<RecursiveZodFormattedError, U2<RecursiveZodFormattedError, U2<RecursiveZodFormattedError, option<obj>>>>
